/* ============================= DECK ============================= */
// FULL_VOCAB: албан ёсны HSK 1-5 (хуучин стандарт, 2500 орчим үг) бүрэн үгийн сан.
// Эх сурвалж: drkameleon/complete-hsk-vocabulary. Формат: [ханз, пиньин, англи, монгол] нэг түвшинд.
function buildDeck(){
  const deck=[];
  LEVELS.forEach(level=>{
    (FULL_VOCAB[level]||[]).forEach((row,wi)=>{
      deck.push({id:level+":w:"+wi, level, h:row[0], p:row[1], en:row[2], m:row[3], rad:row[4]||""});
    });
  });
  return deck;
}
const DECK = buildDeck();

