function normalizeText(s){
  return String(s||"").toLowerCase().replace(/['".,;:()?!]/g, "").replace(/\s+/g, " ").trim();
}
function wordsOf(s){ return normalizeText(s).split(" ").filter(Boolean); }
function topicsForWord(en, mn){
  const wset = new Set(wordsOf(en).concat(wordsOf(mn)));
  const text = normalizeText(en) + " " + normalizeText(mn);
  const hits = [];
  TOPICS.forEach(t=>{
    const wordHit = (t.words||[]).some(w=>wset.has(w));
    const phraseHit = (t.phrases||[]).some(p=>text.includes(p));
    if(wordHit || phraseHit) hits.push(t.key);
  });
  return hits;
}
const WORD_TOPICS = new Map();
DECK.forEach(c=>{ WORD_TOPICS.set(c.id, topicsForWord(c.en, c.m)); });


