/* ============================= RENDER: REVIEW ============================= */
let reviewFilter = "all";
let reviewStandard = "old";
let session = {queue:[], pos:0, flipped:false};

const LEECH_THRESHOLD = 3;
function isLeech(id){ const st = srs.cards[id]; return !!(st && (st.lapses||0)>=LEECH_THRESHOLD); }
function leechCards(){ return DECK.filter(c=>isLeech(c.id)); }

function scopeLabel(key){
  return key==="all" ? "Бүх түвшин" : key==="bookmarks" ? "⭐ Тэмдэглэсэн" : key==="leeches" ? "⚠️ Хүндрэлтэй" : LEVEL_META[key].label;
}

function dueCards(levelFilter){
  if(levelFilter==="leeches") return shuffle(leechCards());
  const pool = levelFilter==="bookmarks" ? DECK.filter(c=>srs.bookmarks && srs.bookmarks[c.id])
    : levelFilter==="all" ? DECK : DECK.filter(c=>c.level===levelFilter);
  const t = todayStr();
  const due = pool.filter(c=>{ const st = srs.cards[c.id]; return st && st.due<=t; });
  const fresh = pool.filter(c=>!srs.cards[c.id]).slice(0,10);
  return shuffle(due.concat(fresh));
}

function renderFilters(containerId, current, onPick, levelsList){
  const box = document.getElementById(containerId);
  box.innerHTML="";
  const opts = ["all"].concat(levelsList||LEVELS).concat(["bookmarks","leeches"]);
  opts.forEach(key=>{
    const chip = document.createElement("button");
    chip.className="chip"+(key===current?" active":"");
    chip.textContent=scopeLabel(key);
    chip.addEventListener("click", ()=>onPick(key));
    box.appendChild(chip);
  });
}

function startSession(){
  renderStandardToggle("review-standard-toggle", reviewStandard, (std)=>{
    reviewStandard = std;
    const list = levelsForStandard(std);
    if(!["all","bookmarks","leeches"].includes(reviewFilter) && !list.includes(reviewFilter)) reviewFilter = "all";
    startSession();
  });
  renderFilters("review-filters", reviewFilter, (key)=>{ reviewFilter=key; startSession(); }, levelsForStandard(reviewStandard));
  session = {queue: dueCards(reviewFilter), pos:0, flipped:false};
  renderCard();
}

function updateHeaderStats(){
  const t = todayStr();
  const due = DECK.filter(c=>{ const st=srs.cards[c.id]; return st && st.due<=t; }).length
    + DECK.filter(c=>!srs.cards[c.id]).length;
  const learned = DECK.filter(c=>srs.cards[c.id]).length;
  document.getElementById("stat-due").textContent = due;
  document.getElementById("stat-learned").textContent = learned;
  document.getElementById("stat-total").textContent = DECK.length;
  document.getElementById("stat-streak").textContent = srs.streak||0;
  const goalInput = document.getElementById("goal-input");
  if(document.activeElement !== goalInput) goalInput.value = srs.dailyGoal||20;
  const todayCount = srs.todayDate===t ? (srs.todayCount||0) : 0;
  document.getElementById("stat-goal-count").textContent = todayCount;
}

function renderCard(){
  updateHeaderStats();
  const slot = document.getElementById("flash-slot");
  const rateRow = document.getElementById("rate-row");
  const bar = document.getElementById("session-bar");
  const count = document.getElementById("session-count");

  const totalQ = session.queue.length;
  count.textContent = totalQ ? `${Math.min(session.pos+1,totalQ)} / ${totalQ}` : "0 / 0";
  bar.style.width = totalQ ? `${Math.min(100, Math.round(100*session.pos/totalQ))}%` : "0%";

  if(session.pos>=totalQ || totalQ===0){
    rateRow.classList.remove("show");
    slot.innerHTML = `
      <div class="empty-state">
        <div class="big">✅</div>
        <h3>Одоогоор давтах юм алга</h3>
        <p>Энэ шүүлтүүрт due карт алга байна. Дараа дахин ирээрэй, эсвэл урьдчилж дасгал хийж болно.</p>
        <button class="btn-primary" id="practice-ahead">Урьдчилж дасгал хийх</button>
      </div>`;
    document.getElementById("practice-ahead").addEventListener("click", ()=>{
      const pool = reviewFilter==="all" ? DECK : DECK.filter(c=>c.level===reviewFilter);
      const sorted = pool.slice().sort((a,b)=>{
        const da = srs.cards[a.id]?srs.cards[a.id].due:todayStr();
        const db_ = srs.cards[b.id]?srs.cards[b.id].due:todayStr();
        return da<db_?-1:da>db_?1:0;
      });
      session = {queue: sorted.slice(0,15), pos:0, flipped:false};
      renderCard();
    });
    return;
  }

  const card = session.queue[session.pos];
  session.flipped=false;
  const el = document.createElement("div");
  el.className="flash";
  el.innerHTML = `<span class="tag">${LEVEL_META[card.level].label}</span>
    ${speakerBtnHtml(card.h, "flash-spk")}
    ${starBtnHtml(card.id, "flash-star")}
    <div class="front-hz">${escapeHtml(card.h)}</div>
    <span class="hint">товшиж эргүүл</span>`;
  el.addEventListener("click", ()=>{
    if(session.flipped) return;
    session.flipped=true;
    el.classList.add("flipped");
    el.innerHTML = `<span class="tag">${LEVEL_META[card.level].label}</span>
      ${speakerBtnHtml(card.h, "flash-spk")}
      ${starBtnHtml(card.id, "flash-star")}
      <div class="front-hz">${escapeHtml(card.h)}</div>
      <div class="back-py">${escapeHtml(card.p)}</div>
      <div class="back-en">${escapeHtml(card.m)}</div>
      ${noteBoxHtml(card.id, "flash-note-box")}
      ${noteBtnHtml(card.id, "flash-note")}`;
    rateRow.classList.add("show");
  });
  slot.innerHTML="";
  slot.appendChild(el);
  rateRow.classList.remove("show");
}

document.getElementById("rate-row").addEventListener("click", (e)=>{
  const btn = e.target.closest(".rate-btn");
  if(!btn || !session.flipped) return;
  const card = session.queue[session.pos];
  rate(card.id, btn.dataset.r);
  session.pos+=1;
  renderCard();
  renderLevelTabs();
});

/* ============================= RENDER: QUIZ ============================= */
let quizScope = "all";
let quizStandard = "old";
let quiz = {questions:[], pos:0, score:0, misses:[], done:false};

function fieldForType(type){ return (type==="meaning"||type==="listening") ? "m" : type==="hanzi" ? "h" : "p"; }

function buildOptions(card, type, pool){
  const key = fieldForType(type);
  const correctVal = card[key];
  const seen = new Set([correctVal]);
  const distractCards = [];
  shuffle(pool.filter(c=>c.id!==card.id)).forEach(c=>{
    if(distractCards.length>=3) return;
    if(seen.has(c[key])) return;
    seen.add(c[key]); distractCards.push(c);
  });
  const options = shuffle(distractCards.concat([card]));
  return options.map(c=>({card:c, isCorrect:c.id===card.id}));
}

/* ---- Sentence fill-in-the-blank (Өгүүлбэр зохиох дасгал), from grammar examples ---- */
function findBlankWord(vocabList, hz){
  const words = vocabList.map(v=>v[0]).filter(w=>w.length>=1 && hz.includes(w));
  if(!words.length) return null;
  words.sort((a,b)=>b.length-a.length);
  return words[0];
}

function collectSentenceCandidates(level){
  const lessons = DATA[level] || [];
  const flatVocab = lessons.flatMap(l=>l.vocab);
  const candidates = [];
  lessons.forEach(lesson=>{
    lesson.grammar.examples.forEach(ex=>{
      const word = findBlankWord(lesson.vocab, ex[0]);
      if(word) candidates.push({level, lessonEn:lesson.en, hz:ex[0], py:ex[1], mn:ex[2], word, flatVocab});
    });
  });
  return candidates;
}

function buildSentenceQuestion(level){
  const cands = collectSentenceCandidates(level);
  if(!cands.length) return null;
  const pick = cands[Math.floor(Math.random()*cands.length)];
  const blanked = pick.hz.replace(pick.word, "▁▁▁");
  const seen = new Set([pick.word]);
  const distractors = [];
  shuffle(pick.flatVocab.filter(v=>v[0]!==pick.word)).forEach(v=>{
    if(distractors.length>=3) return;
    if(seen.has(v[0])) return;
    seen.add(v[0]); distractors.push(v[0]);
  });
  const options = shuffle(distractors.concat([pick.word])).map(w=>({word:w, isCorrect:w===pick.word}));
  if(options.length<2) return null;
  return {kind:"sentence", level, lessonEn:pick.lessonEn, hzBlanked:blanked, hzFull:pick.hz, py:pick.py, mn:pick.mn, options};
}

function extractPatternTokens(patternStr){
  const raw = String(patternStr||"").split(/[\/,]/).flatMap(s=>s.split("..."));
  const tokens = new Set();
  raw.forEach(s=>{
    const matches = s.match(/[一-鿿]+/g);
    if(matches) matches.forEach(m=>{ if(m.length<=6) tokens.add(m); });
  });
  return [...tokens];
}
function allPatternTokens(level){
  const lessons = DATA[level]||[];
  const set = new Set();
  lessons.forEach(l=>{ extractPatternTokens(l.grammar.pattern).forEach(tok=>set.add(tok)); });
  return [...set];
}
function collectGrammarCandidates(level){
  const lessons = DATA[level]||[];
  const candidates = [];
  lessons.forEach(lesson=>{
    const tokens = extractPatternTokens(lesson.grammar.pattern);
    lesson.grammar.examples.forEach(ex=>{
      const tok = tokens.find(t=>ex[0].includes(t));
      if(tok) candidates.push({level, lessonEn:lesson.en, hz:ex[0], py:ex[1], mn:ex[2], tok});
    });
  });
  return candidates;
}
function buildGrammarQuestion(level){
  const cands = collectGrammarCandidates(level);
  if(!cands.length) return null;
  const pick = cands[Math.floor(Math.random()*cands.length)];
  const blanked = pick.hz.replace(pick.tok, "▁▁▁");
  let pool = allPatternTokens(level).filter(t=>t!==pick.tok);
  if(pool.length<3){
    const extra = LEVELS.flatMap(lv=>allPatternTokens(lv)).filter(t=>t!==pick.tok && !pool.includes(t));
    pool = pool.concat(shuffle(extra));
  }
  const distractors = shuffle(pool).slice(0,3);
  const options = shuffle(distractors.concat([pick.tok])).map(w=>({word:w, isCorrect:w===pick.tok}));
  if(options.length<2) return null;
  return {kind:"grammar", level, lessonEn:pick.lessonEn, hzBlanked:blanked, hzFull:pick.hz, py:pick.py, mn:pick.mn, options};
}

function buildQuiz(scope, count, grammarOnly){
  if(grammarOnly){
    const levelsPool = (scope==="all"||scope==="bookmarks"||scope==="leeches") ? LEVELS : [scope];
    const qs = [];
    let guard = 0;
    while(qs.length<count && guard<count*20){
      guard++;
      const lvl = levelsPool[Math.floor(Math.random()*levelsPool.length)];
      const q = Math.random()<0.5 ? buildGrammarQuestion(lvl) : buildSentenceQuestion(lvl);
      if(q) qs.push(q);
    }
    if(qs.length) return qs;
  }
  const pool = scope==="bookmarks" ? DECK.filter(c=>srs.bookmarks && srs.bookmarks[c.id])
    : scope==="leeches" ? leechCards()
    : scope==="all" ? DECK : DECK.filter(c=>c.level===scope);
  const noFallback = scope==="bookmarks" || scope==="leeches";
  const source = noFallback ? (pool.length ? pool : DECK) : (pool.length>=8 ? pool : DECK);
  const picks = shuffle(source).slice(0, Math.min(count, source.length));
  const SENTENCE_CHANCE = 0.18;
  const GRAMMAR_CHANCE = 0.18;
  return picks.map(card=>{
    const roll = Math.random();
    if(roll<SENTENCE_CHANCE){
      const sq = buildSentenceQuestion(card.level);
      if(sq) return sq;
    } else if(roll<SENTENCE_CHANCE+GRAMMAR_CHANCE){
      const gq = buildGrammarQuestion(card.level);
      if(gq) return gq;
    }
    const type = ["meaning","hanzi","pinyin","listening"][Math.floor(Math.random()*4)];
    return {kind:"vocab", card, type, options: buildOptions(card, type, source)};
  });
}

let quizGrammarOnly = false;
let examTimerHandle = null;
const EXAM_MINUTES = 30;
const EXAM_QUESTIONS = 40;

// Real HSK exams are split into timed sections (listening, then reading) whose
// size/duration grows with the level. These counts are modeled on the official
// HSK 1-5 exam structure (reading+writing merged into one "reading" section here,
// since this app has no handwriting/essay grading) so a mock exam here feels like
// the real thing rather than one long undifferentiated question pool.
const EXAM_LEVEL_CONFIG = {
  hsk1:  {listen:20, read:20, listenMin:15, readMin:20},
  hsk2:  {listen:35, read:25, listenMin:25, readMin:25},
  hsk3:  {listen:40, read:40, listenMin:30, readMin:35},
  hsk4:  {listen:45, read:55, listenMin:30, readMin:45},
  hsk5:  {listen:45, read:55, listenMin:30, readMin:60},
  nhsk1: {listen:20, read:20, listenMin:15, readMin:20},
};
const EXAM_DEFAULT_CONFIG = {listen:20, read:20, listenMin:15, readMin:20};
function examConfigFor(scope){ return EXAM_LEVEL_CONFIG[scope] || EXAM_DEFAULT_CONFIG; }

function clearExamTimer(){ if(examTimerHandle){ clearInterval(examTimerHandle); examTimerHandle=null; } }
function currentExamRender(){ return quiz.sectioned ? renderExamQuestion : renderQuizQuestion; }
function startExamTimerTick(){
  clearExamTimer();
  examTimerHandle = setInterval(()=>{
    if(!quiz.examMode){ clearExamTimer(); return; }
    const total = quiz.sectioned ? quiz.sections[quiz.secIdx].questions.length : quiz.questions.length;
    if(quiz.pos>=total){ clearExamTimer(); return; }
    const remain = Math.max(0, quiz.deadline - Date.now());
    const el = document.getElementById("exam-timer-el");
    if(el){
      const mm = Math.floor(remain/60000);
      const ss = Math.floor((remain%60000)/1000);
      el.textContent = `⏱ ${String(mm).padStart(2,"0")}:${String(ss).padStart(2,"0")}`;
      el.classList.toggle("low", remain<60000);
    }
    if(remain<=0){
      clearExamTimer();
      quiz.timedOut = true;
      quiz.pos = total;
      currentExamRender()();
    }
  }, 1000);
}

function renderQuizIntro(){
  clearExamTimer();
  renderStandardToggle("quiz-standard-toggle", quizStandard, (std)=>{
    quizStandard = std;
    const list = levelsForStandard(std);
    if(!["all","bookmarks","leeches"].includes(quizScope) && !list.includes(quizScope)) quizScope = "all";
    renderQuizIntro();
  });
  renderFilters("quiz-filters", quizScope, (key)=>{ quizScope=key; renderQuizIntro(); }, levelsForStandard(quizStandard));
  const body = document.getElementById("quiz-body");
  const key = quizScope;
  const rec = (srs.quiz||{})[key];
  const bestLine = rec ? `<p class="score-sub">Хамгийн сайн дүн: ${rec.best}/${rec.count||10} · ${rec.attempts} удаа өгсөн</p>` : "";
  const examRec = (srs.quiz||{})[key+":exam"];
  const cfg = examConfigFor(key);
  const examTotal = cfg.listen + cfg.read;
  const examMinutesTotal = cfg.listenMin + cfg.readMin;
  const examBestLine = examRec ? `<p class="score-sub">Шалгалтын хамгийн сайн дүн: ${examRec.best}/${examRec.count||examTotal} · ${examRec.attempts} удаа өгсөн</p>` : "";
  body.innerHTML = `
    <div class="quiz-intro">
      <p>${scopeLabel(key)} түвшний үгсээс 10 асуулттай сорил өгнө. Ханз, пиньин, утга, сонсголт (дуудлагаар) болон өгүүлбэрийн хоосон зай нөхөх дасгал холин орох тул сурсан гэдгээ олон талаас бодитоор шалгаж болно.</p>
      <label class="grammar-only-toggle"><input type="checkbox" id="grammar-only" ${quizGrammarOnly?"checked":""}> Зөвхөн дүрмийн дасгал (холбоос үг, өгүүлбэрийн бүтэц)</label>
      ${bestLine}
      <button class="btn-primary" id="start-quiz">Тест эхлүүлэх (10 асуулт)</button>
      <div class="exam-block">
        <p class="score-sub">Эсвэл HSK-ийн албан ёсны шалгалтын бүтцийг дуурайсан, хэсэг тус бүрдээ цагийн хязгаартай <b>дуурайлган шалгалт</b> өгч үзээрэй (жинхэнэ шалгалтын асуулт биш, харин ижил хэв маягаар, ижил бүтэцтэй зохиосон дасгал).</p>
        <div class="exam-structure-note">
          <div class="exam-structure-row">🎧 <b>1-р хэсэг: Сонсголт</b> — ${cfg.listen} асуулт, ${cfg.listenMin} мин</div>
          <div class="exam-structure-row">📖 <b>2-р хэсэг: Унших ойлголт</b> — ${cfg.read} асуулт, ${cfg.readMin} мин</div>
        </div>
        <button class="btn-ghost" id="start-exam">🎓 Дуурайлган шалгалт эхлүүлэх (${examTotal} асуулт, нийт ${examMinutesTotal} мин)</button>
        ${examBestLine}
      </div>
    </div>`;
  document.getElementById("grammar-only").addEventListener("change", (e)=>{ quizGrammarOnly = e.target.checked; });
  document.getElementById("start-quiz").addEventListener("click", ()=>{
    quiz = {questions: buildQuiz(quizScope, 10, quizGrammarOnly), pos:0, score:0, misses:[], done:false};
    renderQuizQuestion();
  });
  document.getElementById("start-exam").addEventListener("click", ()=>{
    startSectionedExam(quizScope);
  });
}

// Builds the prompt/instruction/options markup shared by both the regular
// quiz (renderQuizQuestion) and the sectioned mock exam (renderExamQuestion),
// so the two flows always render a question identically.
function questionDisplayParts(q){
  let promptHtml, instruction, kicker;
  if(q.kind==="sentence" || q.kind==="grammar"){
    kicker = `${LEVEL_META[q.level].label} · ${escapeHtml(q.lessonEn)}`;
    promptHtml = `<div class="quiz-prompt-hz sentence-blank">${escapeHtml(q.hzBlanked)}</div>
      <div class="quiz-prompt-py">${escapeHtml(q.py)}</div>
      <div class="quiz-sentence-mn">${escapeHtml(q.mn)}</div>`;
    instruction = q.kind==="grammar" ? "Дүрмийн зөв холбоос/үгийг сонгоно уу" : "Хоосон зайд тохирох үгийг сонгоно уу";
  } else {
    kicker = LEVEL_META[q.card.level].label;
    const card = q.card;
    if(q.type==="meaning"){
      promptHtml = `<div class="qp-row"><span class="quiz-prompt-hz">${escapeHtml(card.h)}</span>${speakerBtnHtml(card.h)}</div><div class="quiz-prompt-py">${escapeHtml(card.p)}</div>`;
      instruction = "Утгыг сонгоно уу";
    } else if(q.type==="hanzi"){
      promptHtml = `<div class="quiz-prompt-en">${escapeHtml(card.m)}</div>`;
      instruction = "Тохирох ханзыг сонгоно уу";
    } else if(q.type==="listening"){
      promptHtml = `<div class="qp-row"><button type="button" class="spk-btn big" data-say="${escapeHtml(card.h)}" title="Сонсох">🔊</button></div>
        <div class="quiz-listen-reveal" id="listen-reveal"></div>`;
      instruction = "Сонсоод утгыг сонгоно уу";
    } else {
      promptHtml = `<div class="qp-row"><span class="quiz-prompt-hz">${escapeHtml(card.h)}</span>${speakerBtnHtml(card.h)}</div>`;
      instruction = "Пиньиныг сонгоно уу";
    }
  }
  let optsHtml;
  if(q.kind==="sentence" || q.kind==="grammar"){
    optsHtml = q.options.map((o,idx)=>`<button class="qopt" data-idx="${idx}"><span class="qhz">${escapeHtml(o.word)}</span></button>`).join("");
  } else {
    const type = q.type;
    optsHtml = q.options.map((o,idx)=>{
      let inner;
      if(type==="hanzi"){ inner = `<span class="qhz">${escapeHtml(o.card.h)}</span><span class="qpy">${escapeHtml(o.card.p)}</span>`; }
      else if(type==="meaning" || type==="listening"){ inner = `<span class="qtxt">${escapeHtml(o.card.m)}</span>`; }
      else { inner = `<span class="qtxt">${escapeHtml(o.card.p)}</span>`; }
      return `<button class="qopt" data-idx="${idx}">${inner}</button>`;
    }).join("");
  }
  return {kicker, promptHtml, instruction, optsHtml};
}

/* ---- Sectioned mock exam (жинхэнэ HSK шалгалттай ижил бүтэц: Сонсголт → Унших ойлголт, түвшин тус бүрдээ цагтай) ---- */
function buildExamSectionQuestions(scope, count, sectionName){
  const pool = scope==="bookmarks" ? DECK.filter(c=>srs.bookmarks && srs.bookmarks[c.id])
    : scope==="leeches" ? leechCards()
    : scope==="all" ? DECK : DECK.filter(c=>c.level===scope);
  const source = pool.length>=8 ? pool : DECK;
  if(sectionName==="listening"){
    const picks = shuffle(source).slice(0, Math.min(count, source.length));
    return picks.map(card=>({kind:"vocab", card, type:"listening", options: buildOptions(card, "listening", source)}));
  }
  // reading section: mostly meaning/hanzi/pinyin multiple choice, with a
  // sprinkling of sentence/grammar fill-in-the-blank when grammar lessons
  // exist for that card's level (New HSK levels have vocab only, so those
  // cards simply always fall back to plain multiple choice).
  const picks = shuffle(source).slice(0, Math.min(count, source.length));
  const SENTENCE_CHANCE = 0.15, GRAMMAR_CHANCE = 0.15;
  return picks.map(card=>{
    const roll = Math.random();
    let q = null;
    if(roll<SENTENCE_CHANCE) q = buildSentenceQuestion(card.level);
    else if(roll<SENTENCE_CHANCE+GRAMMAR_CHANCE) q = buildGrammarQuestion(card.level);
    if(q) return q;
    const type = ["meaning","hanzi","pinyin"][Math.floor(Math.random()*3)];
    return {kind:"vocab", card, type, options: buildOptions(card, type, source)};
  });
}

function startSectionedExam(scope){
  const cfg = examConfigFor(scope);
  const listenQs = buildExamSectionQuestions(scope, cfg.listen, "listening");
  const readQs = buildExamSectionQuestions(scope, cfg.read, "reading");
  quiz = {
    examMode: true,
    sectioned: true,
    scope,
    sections: [
      {name:"listening", label:"Сонсголт", questions:listenQs, minutes:cfg.listenMin},
      {name:"reading", label:"Унших ойлголт", questions:readQs, minutes:cfg.readMin},
    ],
    secIdx: 0,
    pos: 0,
    score: 0,
    misses: [],
    sectionScores: [{correct:0, total:listenQs.length}, {correct:0, total:readQs.length}],
    deadline: Date.now() + cfg.listenMin*60000,
    timedOut: false,
    done: false,
  };
  renderExamQuestion();
}

function renderExamQuestion(){
  const body = document.getElementById("quiz-body");
  const section = quiz.sections[quiz.secIdx];
  const isLastSection = quiz.secIdx === quiz.sections.length-1;

  if(quiz.pos>=section.questions.length){
    clearExamTimer();
    if(!isLastSection){
      const sc = quiz.sectionScores[quiz.secIdx];
      const nextSection = quiz.sections[quiz.secIdx+1];
      body.innerHTML = `
        <div class="quiz-results exam-section-done">
          <div class="quiz-kicker">${section.label} дуусав</div>
          <div class="score-big">${sc.correct}/${sc.total}</div>
          <p class="score-sub">Дараагийн хэсэг: <b>${nextSection.label}</b> — ${nextSection.questions.length} асуулт, ${nextSection.minutes} мин</p>
          <div class="quiz-actions">
            <button class="btn-primary" id="exam-next-section">Дараагийн хэсэг рүү →</button>
          </div>
        </div>`;
      document.getElementById("exam-next-section").addEventListener("click", ()=>{
        quiz.secIdx += 1;
        quiz.pos = 0;
        quiz.timedOut = false;
        quiz.deadline = Date.now() + quiz.sections[quiz.secIdx].minutes*60000;
        renderExamQuestion();
      });
      return;
    }
    const total = quiz.sections.reduce((a,s)=>a+s.questions.length, 0);
    recordQuiz(quiz.scope+":exam", quiz.score, total);
    const pct = total ? Math.round(quiz.score/total*100) : 0;
    const passNote = pct>=60
      ? `<p class="score-sub exam-pass-note exam-pass-ok">✅ Ойролцоогоор тэнцэх түвшний оноо (≥60%) — гэхдээ энэ бол зөвхөн дасгалын тооцоолол, албан ёсны шалгалтын дүн биш.</p>`
      : `<p class="score-sub exam-pass-note exam-pass-low">📈 Ойролцоогоор 60%-иас доош байна — дахин давтаж үзээрэй.</p>`;
    const sectionBreakdown = quiz.sections.map((s,i)=>`
      <div class="exam-sec-row"><span>${s.label}</span><span>${quiz.sectionScores[i].correct}/${quiz.sectionScores[i].total}</span></div>
    `).join("");
    const timeoutNote = quiz.timedOut ? `<p class="score-sub" style="color:var(--seal);">⏱ Цаг дууссан тул үлдсэн асуултууд алгасагдав.</p>` : "";
    const missItems = quiz.misses.map(m=>{
      if(m.kind==="sentence" || m.kind==="grammar"){
        return `<div class="miss-item">
          <span class="hz">${escapeHtml(m.hzFull)}</span>
          <span class="mi-en">${escapeHtml(m.mn)}</span>
        </div>`;
      }
      return `<div class="miss-item">
        <span class="hz">${escapeHtml(m.card.h)}<span class="mi-py">${escapeHtml(m.card.p)}</span></span>
        <span class="mi-en">${escapeHtml(m.card.m)}</span>
        ${starBtnHtml(m.card.id, "miss-star")}
      </div>`;
    }).join("");
    body.innerHTML = `
      <div class="quiz-results">
        <div class="quiz-kicker">${scopeLabel(quiz.scope)} · Дуурайлган шалгалтын дүн</div>
        <div class="score-big">${quiz.score}/${total} <span class="exam-pct">(${pct}%)</span></div>
        <div class="exam-sec-breakdown">${sectionBreakdown}</div>
        ${timeoutNote}
        ${passNote}
        <p class="score-sub">${quiz.misses.length===0 ? "Гайхалтай! Бүх асуултад зөв хариулав." : "Дараах үгсийг дахин давтвал зүгээр."}</p>
        ${missItems ? `<div class="miss-list">${missItems}</div>` : ""}
        <div class="quiz-actions">
          <button class="btn-primary" id="quiz-retry">Дахин турших</button>
          <button class="btn-ghost" id="quiz-back">Түвшин сонгох</button>
        </div>
      </div>`;
    document.getElementById("quiz-retry").addEventListener("click", ()=>{ startSectionedExam(quiz.scope); });
    document.getElementById("quiz-back").addEventListener("click", renderQuizIntro);
    return;
  }

  startExamTimerTick();

  const q = section.questions[quiz.pos];
  const {kicker, promptHtml, instruction, optsHtml} = questionDisplayParts(q);

  body.innerHTML = `
    <div class="session-count" style="text-align:center;margin-bottom:14px;">${section.label} — Асуулт ${quiz.pos+1} / ${section.questions.length} · ${scopeLabel(quiz.scope)}</div>
    <div class="quiz-card">
      <div class="exam-timer" id="exam-timer-el">⏱ --:--</div>
      <div class="exam-section-badge">${quiz.secIdx+1}-р хэсэг: ${section.label}</div>
      <div class="quiz-kicker">${kicker}</div>
      ${promptHtml}
      <div class="quiz-instruction">${instruction}</div>
      <div class="quiz-options">${optsHtml}</div>
      <div class="quiz-next-wrap" id="quiz-next-wrap"></div>
    </div>`;

  if(q.kind==="vocab" && q.type==="listening") speak(q.card.h);

  const optButtons = body.querySelectorAll(".qopt");
  optButtons.forEach(btn=>{
    btn.addEventListener("click", ()=>{
      optButtons.forEach(b=>b.disabled=true);
      const idx = Number(btn.dataset.idx);
      const chosen = q.options[idx];
      const secScore = quiz.sectionScores[quiz.secIdx];
      if(chosen.isCorrect){
        btn.classList.add("correct"); quiz.score+=1; secScore.correct+=1;
      } else {
        btn.classList.add("wrong");
        if(q.kind==="sentence"){ quiz.misses.push({kind:"sentence", hzFull:q.hzFull, mn:q.mn}); }
        else if(q.kind==="grammar"){ quiz.misses.push({kind:"grammar", hzFull:q.hzFull, mn:q.mn}); }
        else{ quiz.misses.push({kind:"vocab", card:q.card}); recordQuizMiss(q.card.id); }
        const correctBtn = Array.from(optButtons).find((b,i)=>q.options[i].isCorrect);
        if(correctBtn) correctBtn.classList.add("correct");
      }
      if(q.kind==="vocab" && q.type==="listening"){
        const reveal = document.getElementById("listen-reveal");
        if(reveal) reveal.textContent = `${q.card.h} (${q.card.p})`;
      }
      const nextWrap = document.getElementById("quiz-next-wrap");
      const isLastInSection = quiz.pos===section.questions.length-1;
      const nextBtn = document.createElement("button");
      nextBtn.className="btn-primary";
      nextBtn.textContent = isLastInSection ? (isLastSection ? "Дүн харах" : "Хэсэг дуусгах") : "Дараах асуулт";
      nextBtn.addEventListener("click", ()=>{ quiz.pos+=1; renderExamQuestion(); });
      nextWrap.appendChild(nextBtn);
    });
  });
}

