let dlgLevel = "hsk1";
let dlgActive = null;   // index into DIALOGUES[dlgLevel]
let dlgShowTrans = true;
let dlgAnswers = {};

function renderDialogueFilters(){
  const box = document.getElementById("games-dialogue-filters");
  box.innerHTML = "";
  LEVELS.forEach(lv=>{
    const chip = document.createElement("button");
    chip.className = "chip"+(lv===dlgLevel?" active":"");
    chip.textContent = LEVEL_META[lv].label;
    chip.addEventListener("click", ()=>{ dlgLevel=lv; dlgActive=null; renderDialogueFilters(); renderDialogueGame(); });
    box.appendChild(chip);
  });
}

function renderDialogueGame(){
  const box = document.getElementById("games-body");
  const list = DIALOGUES[dlgLevel]||[];
  if(dlgActive==null){
    if(!list.length){ box.innerHTML = `<div class="empty-state"><p>Энэ түвшинд одоогоор яриа алга.</p></div>`; return; }
    box.innerHTML = `<div class="dlg-picker">
      ${list.map((d,i)=>`<button class="dlg-pick-btn" data-i="${i}">
        <div class="dlg-t">${escapeHtml(d.title)}</div>
        <div class="dlg-sub">${escapeHtml(d.desc)}</div>
      </button>`).join("")}
    </div>`;
    box.querySelectorAll(".dlg-pick-btn").forEach(btn=>{
      btn.addEventListener("click", ()=>{ dlgActive = Number(btn.dataset.i); dlgShowTrans = true; dlgAnswers = {}; renderDialogueGame(); });
    });
    return;
  }
  const d = list[dlgActive];
  const linesHtml = d.lines.map((ln,i)=>{
    const side = i%2===0 ? "a" : "b";
    return `<div class="dlg-line ${side}">
      <div class="dlg-avatar">${escapeHtml(ln.spk[0])}</div>
      <div class="dlg-bubble ${dlgShowTrans?"":"hide-trans"}">
        <div class="dlg-hz">${escapeHtml(ln.hz)} ${speakerBtnHtml(ln.hz,"")}</div>
        <div class="dlg-py">${escapeHtml(ln.py)}</div>
        <div class="dlg-mn">${escapeHtml(ln.mn)}</div>
      </div>
    </div>`;
  }).join("");
  const qHtml = (d.questions||[]).map((q,qi)=>{
    const answered = dlgAnswers[qi]!=null;
    const optsHtml = q.opts.map((opt,oi)=>{
      let cls = "qopt dlg-opt";
      if(answered){
        if(oi===q.answer) cls += " correct";
        else if(oi===dlgAnswers[qi]) cls += " wrong";
      }
      return `<button class="${cls}" data-q="${qi}" data-oi="${oi}" ${answered?"disabled":""}><span class="qtxt">${escapeHtml(opt)}</span></button>`;
    }).join("");
    return `<div class="spk-qa-item">
      <div style="font-weight:600;margin-bottom:8px;font-size:.86rem;">${qi+1}. ${escapeHtml(q.q)}</div>
      <div class="quiz-options" style="grid-template-columns:1fr 1fr;max-width:100%;">${optsHtml}</div>
    </div>`;
  }).join("");
  box.innerHTML = `
    <div class="dlg-stage">
      <div class="dlg-actions">
        <button class="btn-ghost" id="dlg-back">← Жагсаалт руу</button>
        ${ttsSupported?`<button class="btn-primary" id="dlg-play-all">▶ Бүгдийг сонсох</button>`:""}
      </div>
      <label class="dlg-toggle"><input type="checkbox" id="dlg-trans-toggle" ${dlgShowTrans?"checked":""}> Орчуулга харуулах</label>
      ${linesHtml}
      ${qHtml ? `<h4 style="font-family:'Noto Serif SC',serif;font-size:.92rem;margin:22px 0 12px;">Ойлголтын асуулт</h4>${qHtml}` : ""}
    </div>
  `;
  document.getElementById("dlg-back").addEventListener("click", ()=>{ dlgActive=null; renderDialogueGame(); });
  const playBtn = document.getElementById("dlg-play-all");
  if(playBtn) playBtn.addEventListener("click", ()=> speakSequence(d.lines.map(l=>l.hz)) );
  const transToggle = document.getElementById("dlg-trans-toggle");
  if(transToggle) transToggle.addEventListener("change", (e)=>{ dlgShowTrans = e.target.checked; renderDialogueGame(); });
  box.querySelectorAll(".dlg-opt").forEach(btn=>{
    btn.addEventListener("click", ()=>{
      const qi = Number(btn.dataset.q), oi = Number(btn.dataset.oi);
      if(dlgAnswers[qi]!=null) return;
      dlgAnswers[qi] = oi;
      renderDialogueGame();
    });
  });
}

