/* ============================= ПРОФАЙЛ ХУУДАС ============================= */
function searchDeckCards(query, limit){
  const q = String(query||"").trim().toLowerCase();
  if(!q) return [];
  const out = [];
  for(const c of DECK){
    if(c.h.toLowerCase().includes(q) || c.p.toLowerCase().includes(q) || c.m.toLowerCase().includes(q)){
      out.push(c);
      if(out.length>=limit) break;
    }
  }
  return out;
}

let profileDeckBuilderSelected = [];
let profileDeckDeleteArmed = null;

function renderDeckBuilderSelected(){
  const box = document.getElementById("pp-deck-selected");
  if(!box) return;
  if(!profileDeckBuilderSelected.length){
    box.innerHTML = `<p class="prog-empty">Одоогоор үг сонгоогүй байна.</p>`;
    return;
  }
  box.innerHTML = profileDeckBuilderSelected.map(id=>{
    const c = DECK.find(x=>x.id===id);
    if(!c) return "";
    return `<span class="deck-chip">${escapeHtml(c.h)}<button type="button" class="deck-chip-x" data-remove-selected="${escapeHtml(id)}">✕</button></span>`;
  }).join("");
}

