function wireProfilePage(body){
  if(body.dataset.wired) return; // delegated listener stays valid across re-renders — attach once
  body.dataset.wired = "1";

  body.addEventListener("click", (e)=>{
    const avatarToggle = e.target.closest("#pp-avatar-toggle");
    if(avatarToggle){
      const grid = document.getElementById("pp-avatar-grid");
      if(grid) grid.hidden = !grid.hidden;
      return;
    }
    const emojiBtn = e.target.closest(".avatar-emoji-btn");
    if(emojiBtn){
      srs.avatarEmoji = emojiBtn.dataset.emoji;
      scheduleSave();
      publishLeaderboardNow();
      renderProfileBlock();
      renderProfilePage();
      return;
    }
    const saveNameBtn = e.target.closest("#pp-save-name");
    if(saveNameBtn){
      const nickInput = document.getElementById("pp-nickname");
      const chalInput = document.getElementById("pp-challenge");
      const msg = document.getElementById("pp-name-msg");
      srs.nickname = ((nickInput&&nickInput.value)||"").trim().slice(0,24);
      srs.challenge = ((chalInput&&chalInput.value)||"").trim().slice(0,60);
      scheduleSave();
      publishLeaderboardNow();
      renderProfileBlock();
      if(msg){ msg.textContent = "Хадгаллаа."; msg.className = "pp-msg pp-msg-ok"; }
      return;
    }
    const saveGoalBtn = e.target.closest("#pp-save-goal");
    if(saveGoalBtn){
      const lvSel = document.getElementById("pp-exam-level");
      const dateInp = document.getElementById("pp-exam-date");
      const msg = document.getElementById("pp-goal-msg");
      const level = lvSel ? lvSel.value : "";
      const date = dateInp ? dateInp.value : "";
      srs.examGoal = (level && date) ? {level, date} : null;
      scheduleSave();
      const countdownBox = document.getElementById("pp-goal-countdown");
      if(countdownBox) countdownBox.innerHTML = examCountdownHtml();
      if(msg){ msg.textContent = srs.examGoal ? "Зорилго хадгаллаа." : "Зорилгыг цэвэрлэлээ."; msg.className = "pp-msg pp-msg-ok"; }
      return;
    }
    const deckViewBtn = e.target.closest("[data-deck-view]");
    if(deckViewBtn){
      const id = deckViewBtn.dataset.deckView;
      const box = document.getElementById("deck-words-"+id);
      if(!box) return;
      if(box.hidden){
        const deck = (srs.customDecks||{})[id];
        const cards = deck ? deck.cardIds.map(cid=>DECK.find(c=>c.id===cid)).filter(Boolean) : [];
        box.innerHTML = cards.length ? `<table class="vb-table"><thead><tr><th>Ханз</th><th>Пиньин</th><th>Утга</th><th></th></tr></thead><tbody>${cards.map(c=>`
          <tr><td class="hz">${escapeHtml(c.h)}</td><td class="py">${escapeHtml(c.p)}</td><td class="en-def">${escapeHtml(c.m)}</td>
          <td><button type="button" class="deck-row-btn" data-deck-remove-card="${escapeHtml(id)}|${escapeHtml(c.id)}">✕</button></td></tr>`).join("")}</tbody></table>`
          : `<p class="prog-empty">Энэ багцад үг алга.</p>`;
        box.hidden = false;
      } else {
        box.hidden = true;
      }
      return;
    }
    const deckDelBtn = e.target.closest("[data-deck-del]");
    if(deckDelBtn){
      const id = deckDelBtn.dataset.deckDel;
      if(profileDeckDeleteArmed===id){
        deleteCustomDeck(id);
        profileDeckDeleteArmed = null;
      } else {
        profileDeckDeleteArmed = id;
        setTimeout(()=>{
          if(profileDeckDeleteArmed===id){ profileDeckDeleteArmed=null; renderProfilePage(); }
        }, 3000);
      }
      renderProfilePage();
      return;
    }
    const removeCardBtn = e.target.closest("[data-deck-remove-card]");
    if(removeCardBtn){
      const [deckId, cardId] = removeCardBtn.dataset.deckRemoveCard.split("|");
      removeCardFromDeck(deckId, cardId);
      renderProfilePage();
      return;
    }
    const deckCreateToggle = e.target.closest("#pp-deck-create-toggle");
    if(deckCreateToggle){
      const builder = document.getElementById("pp-deck-builder");
      profileDeckBuilderSelected = [];
      if(builder){ builder.hidden = !builder.hidden; }
      renderDeckBuilderSelected();
      return;
    }
    const addCardBtn = e.target.closest("[data-add-card]");
    if(addCardBtn){
      const id = addCardBtn.dataset.addCard;
      if(!profileDeckBuilderSelected.includes(id)) profileDeckBuilderSelected.push(id);
      renderDeckBuilderSelected();
      const search = document.getElementById("pp-deck-search");
      if(search) search.dispatchEvent(new Event("input"));
      return;
    }
    const removeSelBtn = e.target.closest("[data-remove-selected]");
    if(removeSelBtn){
      const id = removeSelBtn.dataset.removeSelected;
      profileDeckBuilderSelected = profileDeckBuilderSelected.filter(x=>x!==id);
      renderDeckBuilderSelected();
      return;
    }
    const deckSaveBtn = e.target.closest("#pp-deck-save");
    if(deckSaveBtn){
      const nameInput = document.getElementById("pp-deck-name");
      const name = (nameInput&&nameInput.value)||"";
      if(!name.trim()){
        if(nameInput) nameInput.focus();
        return;
      }
      createCustomDeck(name, profileDeckBuilderSelected);
      profileDeckBuilderSelected = [];
      renderProfilePage();
      return;
    }
    const savePwBtn = e.target.closest("#pp-save-pw");
    if(savePwBtn){
      const cur = document.getElementById("pp-cur-pw");
      const next = document.getElementById("pp-new-pw");
      const msg = document.getElementById("pp-pw-msg");
      const currentPassword = (cur&&cur.value)||"";
      const newPassword = (next&&next.value)||"";
      if(!currentPassword || !newPassword){
        if(msg){ msg.textContent = "Одоогийн болон шинэ нууц үгээ бүгдийг оруулна уу."; msg.className = "pp-msg pp-msg-err"; }
        return;
      }
      fetch("/api/change-password", {
        method:"POST", headers:{"Content-Type":"application/json"},
        body: JSON.stringify({currentPassword, newPassword}),
      }).then(async res=>{
        const data = await res.json().catch(()=>({}));
        if(!res.ok){
          if(msg){ msg.textContent = data.error || "Алдаа гарлаа."; msg.className = "pp-msg pp-msg-err"; }
          return;
        }
        if(msg){ msg.textContent = "Нууц үг амжилттай солигдлоо."; msg.className = "pp-msg pp-msg-ok"; }
        if(cur) cur.value = "";
        if(next) next.value = "";
      }).catch(()=>{
        if(msg){ msg.textContent = "Сүлжээний алдаа гарлаа."; msg.className = "pp-msg pp-msg-err"; }
      });
      return;
    }
  });

  body.addEventListener("input", (e)=>{
    if(e.target.id==="pp-deck-search"){
      const results = searchDeckCards(e.target.value, 8);
      const box = document.getElementById("pp-deck-results");
      if(!box) return;
      box.innerHTML = results.length ? results.map(c=>{
        const already = profileDeckBuilderSelected.includes(c.id);
        return `<div class="deck-result-row">
          <span class="hz-cell">${escapeHtml(c.h)}</span>
          <span class="py">${escapeHtml(c.p)}</span>
          <span class="en-def">${escapeHtml(c.m)}</span>
          <button type="button" class="deck-row-btn" data-add-card="${escapeHtml(c.id)}" ${already?"disabled":""}>${already?"✓ Нэмсэн":"+ Нэмэх"}</button>
        </div>`;
      }).join("") : (e.target.value.trim() ? `<p class="prog-empty">Илэрц алга.</p>` : "");
    }
  });
}

/* ============================= VIEW SWITCH ============================= */
function switchView(view){
  if(view!=="quiz") clearExamTimer();
  document.getElementById("tab-lessons").classList.toggle("active", view==="lessons");
  const tabGrammar = document.getElementById("tab-grammar");
  if(tabGrammar) tabGrammar.classList.toggle("active", view==="grammar");
  document.getElementById("tab-review").classList.toggle("active", view==="review");
  document.getElementById("tab-quiz").classList.toggle("active", view==="quiz");
  document.getElementById("tab-games").classList.toggle("active", view==="games");
  document.getElementById("tab-progress").classList.toggle("active", view==="progress");
  const tabLb = document.getElementById("tab-leaderboard");
  if(tabLb) tabLb.classList.toggle("active", view==="leaderboard");
  document.getElementById("lessons-view").classList.toggle("hidden", view!=="lessons");
  const grammarView = document.getElementById("grammar-view");
  if(grammarView) grammarView.classList.toggle("active", view==="grammar");
  document.getElementById("review-view").classList.toggle("active", view==="review");
  document.getElementById("quiz-view").classList.toggle("active", view==="quiz");
  document.getElementById("games-view").classList.toggle("active", view==="games");
  document.getElementById("progress-view").classList.toggle("active", view==="progress");
  const lbView = document.getElementById("leaderboard-view");
  if(lbView) lbView.classList.toggle("active", view==="leaderboard");
  const profileView = document.getElementById("profile-view");
  if(profileView) profileView.classList.toggle("active", view==="profile");
  if(view==="grammar") renderGrammarIndex();
  if(view==="review") startSession();
  if(view==="quiz") renderQuizIntro();
  if(view==="games") renderGamesIntro();
  if(view==="progress") renderProgress();
  if(view==="leaderboard") renderLeaderboardPage();
  if(view==="profile") renderProfilePage();
}
