/* ============================= НЭВТРЭЛТ / ПРОФАЙЛ / ГАРАХ ============================= */
function displayNameFromEmail(email){
  const local = String(email||"").split("@")[0].replace(/[0-9._-]+$/,"").trim();
  const base = local || String(email||"").split("@")[0] || "Хэрэглэгч";
  return base.charAt(0).toUpperCase() + base.slice(1);
}
function renderProfileBlock(){
  const name = srs.nickname || displayNameFromEmail(CURRENT_USER.email);
  const emoji = srs.avatarEmoji || "";
  const glyph = avatarGlyphRaw(name, emoji);
  const nameEl = document.getElementById("profile-name");
  const avatarEl = document.getElementById("profile-avatar");
  const emailEl = document.getElementById("profile-menu-email");
  const bigNameEl = document.getElementById("pm-name-big");
  const bigAvatarEl = document.getElementById("pm-avatar-big");
  if(nameEl) nameEl.textContent = name;
  if(avatarEl){ avatarEl.textContent = glyph; avatarEl.style.background = emoji ? "transparent" : avatarColor(name); }
  if(bigNameEl) bigNameEl.textContent = name;
  if(bigAvatarEl){ bigAvatarEl.textContent = glyph; bigAvatarEl.style.background = emoji ? "transparent" : avatarColor(name); }
  if(emailEl) emailEl.textContent = CURRENT_USER.email || "";
}

/* ---- Өнгөний горим (Цайвар/Бараан унтраалга) ---- */
function getThemeChoice(){
  // Хуучин хувилбарт "system" гэсэн сонголт хадгалагдсан байж болзошгүй тул
  // "light"/"dark" биш утгыг бүгдийг систем горим гэж үзнэ.
  try{
    const v = localStorage.getItem("hsk-theme");
    return (v==="light" || v==="dark") ? v : "system";
  }catch(e){ return "system"; }
}
function isDarkEffective(){
  const choice = getThemeChoice();
  if(choice==="dark") return true;
  if(choice==="light") return false;
  try{ return window.matchMedia && window.matchMedia("(prefers-color-scheme: dark)").matches; }catch(e){ return false; }
}
function applyTheme(choice){
  if(choice==="light" || choice==="dark") document.documentElement.setAttribute("data-theme", choice);
  else document.documentElement.removeAttribute("data-theme");
}
function setThemeChoice(choice){
  try{ localStorage.setItem("hsk-theme", choice); }catch(e){}
  applyTheme(choice);
  renderThemeToggle();
}
function renderThemeToggle(){
  const cb = document.getElementById("pm-theme-toggle");
  const dark = isDarkEffective();
  if(cb) cb.checked = dark;
  const lightSide = document.querySelector(".pm-theme-side-light");
  const darkSide = document.querySelector(".pm-theme-side-dark");
  if(lightSide) lightSide.classList.toggle("pm-theme-side-active", !dark);
  if(darkSide) darkSide.classList.toggle("pm-theme-side-active", dark);
}

/* ---- Оффлайнд ашиглах (үндсэн app shell-ийг service worker-ээр кэшлэх) ---- */
function isOfflineEnabled(){
  try{ return localStorage.getItem("hsk-offline")==="1"; }catch(e){ return false; }
}
async function setOfflineEnabled(on){
  try{ localStorage.setItem("hsk-offline", on?"1":"0"); }catch(e){}
  if(!("serviceWorker" in navigator)) return;
  try{
    if(on){
      await navigator.serviceWorker.register("/sw.js");
    } else {
      const regs = await navigator.serviceWorker.getRegistrations();
      for(const r of regs) await r.unregister();
      if(typeof caches!=="undefined" && caches.keys){
        const keys = await caches.keys();
        await Promise.all(keys.map(k=>caches.delete(k)));
      }
    }
  }catch(e){ /* offline caching is a nice-to-have — never break the app over it */ }
}
function initOfflineToggle(){
  const cb = document.getElementById("pm-offline-toggle");
  if(!cb) return;
  const on = isOfflineEnabled();
  cb.checked = on;
  if(on) setOfflineEnabled(true); // re-register on every load so caching stays warm
  cb.addEventListener("change", ()=>setOfflineEnabled(cb.checked));
}

(function(){
  const trigger = document.getElementById("profile-trigger");
  const menu = document.getElementById("profile-menu");
  const block = document.getElementById("profile-block");
  if(!trigger || !menu || !block) return;
  function closeMenu(){ menu.hidden = true; trigger.setAttribute("aria-expanded", "false"); }
  trigger.addEventListener("click", (e)=>{
    e.stopPropagation();
    const open = menu.hidden;
    menu.hidden = !open;
    trigger.setAttribute("aria-expanded", open ? "true" : "false");
  });
  document.addEventListener("click", (e)=>{
    if(!menu.hidden && !block.contains(e.target)) closeMenu();
  });
  document.addEventListener("keydown", (e)=>{ if(e.key==="Escape") closeMenu(); });
  const gotoProfile = document.getElementById("pm-goto-profile");
  if(gotoProfile) gotoProfile.addEventListener("click", ()=>{
    closeMenu();
    switchView("profile");
  });
  const themeToggle = document.getElementById("pm-theme-toggle");
  if(themeToggle) themeToggle.addEventListener("change", ()=>{
    setThemeChoice(themeToggle.checked ? "dark" : "light");
  });
  applyTheme(getThemeChoice());
  renderThemeToggle();
  initOfflineToggle();
  const voiceSelect = document.getElementById("pm-voice-select");
  if(voiceSelect) voiceSelect.addEventListener("change", ()=>setZhVoice(voiceSelect.value));
  const voiceTest = document.getElementById("pm-voice-test");
  if(voiceTest) voiceTest.addEventListener("click", ()=>speak("你好，很高兴认识你。"));
  renderVoicePicker(); // in case voices were already loaded before this IIFE ran
})();

